function mp_botanical_values($json){
 $data=json_decode((string)$json,true);$saved=is_array($data['botanical_elegance'] ?? null)?$data['botanical_elegance']:[];$values=[];
 foreach(mp_botanical_fields() as $key=>$field)$values[$key]=isset($saved[$key])&&is_string($saved[$key])&&trim($saved[$key])!==''?$saved[$key]:$field['default'];return $values;
}
